pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract TrustQuestsPayment is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // Trust token contract on Intuition chain
    IERC20 public immutable trustToken;

    // Authorized withdrawal address
    address public constant AUTHORIZED_WITHDRAWER = 0xec48e65C2AD6d242F173467EC3edc7AAD78CFA07;

    // Pro plan price: 10 TRUST (with 18 decimals)
    uint256 public constant PRO_PLAN_PRICE = 10 * 10**18;

    // User pro status
    mapping(address => bool) public hasPaidPro;
    mapping(address => uint256) public paymentTimestamps;

    // Emergency controls
    bool public paused;

    // Events
    event ProPaymentReceived(address indexed user, uint256 amount, uint256 timestamp);
    event FundsWithdrawn(address indexed to, uint256 amount, address indexed by);
    event EmergencyPaused(address indexed by);
    event EmergencyUnpaused(address indexed by);

    modifier notPaused() {
        require(!paused, "Contract is paused");
        _;
    }

    modifier onlyAuthorizedWithdrawer() {
        require(msg.sender == AUTHORIZED_WITHDRAWER, "Not authorized to withdraw");
        _;
    }

    /**
     * @dev Constructor
     * @param _trustTokenAddress TRUST token contract address on Intuition chain
     */
    constructor(address _trustTokenAddress) {
        require(_trustTokenAddress != address(0), "Invalid token address");
        trustToken = IERC20(_trustTokenAddress);
    }

    /**
     * @dev Pay for Pro plan with TRUST tokens
     * User must approve contract to spend tokens before calling
     */
    function payForPro() external notPaused nonReentrant {
        require(!hasPaidPro[msg.sender], "Already a pro user");

        // Transfer TRUST tokens from user to contract
        trustToken.safeTransferFrom(msg.sender, address(this), PRO_PLAN_PRICE);

        // Update user status
        hasPaidPro[msg.sender] = true;
        paymentTimestamps[msg.sender] = block.timestamp;

        emit ProPaymentReceived(msg.sender, PRO_PLAN_PRICE, block.timestamp);
    }

    /**
     * @dev Check if user has pro status
     * @param user Address to check
     */
    function isProUser(address user) external view returns (bool) {
        return hasPaidPro[user];
    }

    /**
     * @dev Get contract TRUST token balance
     */
    function getContractBalance() external view returns (uint256) {
        return trustToken.balanceOf(address(this));
    }

    // ========================================
    // WITHDRAWAL FUNCTIONS (AUTHORIZED ONLY)
    // ========================================

    /**
     * @dev Emergency pause all payments
     */
    function pause() external onlyAuthorizedWithdrawer {
        paused = true;
        emit EmergencyPaused(msg.sender);
    }

    /**
     * @dev Emergency unpause payments
     */
    function unpause() external onlyAuthorizedWithdrawer {
        paused = false;
        emit EmergencyUnpaused(msg.sender);
    }

    /**
     * @dev Withdraw specific amount of TRUST tokens
     * @param to Recipient address
     * @param amount Amount to withdraw (in wei)
     */
    function withdrawFunds(address to, uint256 amount) external onlyAuthorizedWithdrawer {
        require(to != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be positive");
        require(amount <= trustToken.balanceOf(address(this)), "Insufficient balance");

        trustToken.safeTransfer(to, amount);
        emit FundsWithdrawn(to, amount, msg.sender);
    }

    /**
     * @dev Withdraw all accumulated TRUST tokens to authorized withdrawer
     * @param to Recipient address
     */
    function withdrawAllFunds(address to) external onlyAuthorizedWithdrawer {
        require(to != address(0), "Invalid recipient");

        uint256 balance = trustToken.balanceOf(address(this));
        require(balance > 0, "No funds to withdraw");

        trustToken.safeTransfer(to, balance);
        emit FundsWithdrawn(to, balance, msg.sender);
    }
}

